// ── self-checks (throw on violation; tolerances = the 8-sig-fig bake) ────────
export const W1_LANDSCAPE_ASSERTIONS = [
  {
    id: 'w1viz-binned-sup-pins-grid-sup',
    description: 'the max of the baked MX arrays equals the recorded grid sup literals (max-preserving binning)',
    holds: () => {
      const sp = Math.max(Math.max(...PILOT_S0.MX), Math.max(...PILOT_S1.MX));
      const se = Math.max(Math.max(...E97_S0.MX), Math.max(...E97_S1.MX));
      return (
        Math.abs(sp - W1_LANDSCAPE_META.gridSupPilot.value) < 1e-8 &&
        Math.abs(se - W1_LANDSCAPE_META.gridSupE97.value) < 1e-8
      );
    },
  },
  {
    id: 'w1viz-everything-below-rex',
    description: 'every baked sample (max and min, all four series, zoom included) is below Rex — the pilot PASS restated on the baked data',
    holds: () => {
      const R = W1_LANDSCAPE_META.rexExact;
      const all = [PILOT_S0, E97_S0, PILOT_S1, E97_S1];
      return (
        all.every((s) => s.MX.every((v) => v < R) && s.MN.every((v) => v >= 0)) &&
        ZOOM_PILOT_S0.every((v) => v < R) &&
        ZOOM_E97_S0.every((v) => v < R)
      );
    },
  },
  {
    id: 'w1viz-zoom-brackets-refined-sup',
    description: 'the raw 0.017-x-unit stretch peaks at 0.24377885 — within 5e-5 of the recorded zoom-refined sup (the finer sampling sits 2.471e-5 ABOVE the pilot 3-level zoom: a sampled sup, not a continuum bound) and below Rex',
    holds: () => {
      const m = Math.max(...ZOOM_PILOT_S0);
      return (
        Math.abs(m - W1_LANDSCAPE_META.supPilot.value) < 5e-5 &&
        m < W1_LANDSCAPE_META.rexExact &&
        Math.abs(m - 0.24377885) < 1e-12
      );
    },
  },
  {
    id: 'w1viz-shapes',
    description: '3000 bins per series, monotone W, zoom length 2001',
    holds: () =>
      [PILOT_S0, E97_S0, PILOT_S1, E97_S1].every(
        (s) => s.W.length === 3000 && s.MX.length === 3000 && s.MN.length === 3000 &&
          s.W.every((w, i) => i === 0 || w > s.W[i - 1])
      ) && ZOOM_PILOT_S0.length === 2001 && ZOOM_E97_S0.length === 2001,
  },
  {
    id: 'w1viz-seam-charts-agree-at-bin-scale',
    description: 'the two seam charts track each other (|MX0 - MX1| small at every bin — the recorded cross-chart agreement)',
    holds: () =>
      PILOT_S0.MX.every((v, i) => Math.abs(v - PILOT_S1.MX[i]) < 5e-3) &&
      E97_S0.MX.every((v, i) => Math.abs(v - E97_S1.MX[i]) < 5e-3),
  },
];

for (const a of W1_LANDSCAPE_ASSERTIONS) {
  if (!a.holds()) throw new Error(`viz-window1-landscape-data assertion failed: ${a.id}`);
}
